import{_ as l,l as r,o as e,c as s,v as n,p as i,x as t,d as c,i as I,S as d}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"Flynn 分类","description":"","frontmatter":{"title":"Flynn 分类","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/flynn-taxonomy.md","filePath":"cs/flynn-taxonomy.md","lastUpdated":1789023840000}'),E={name:"cs/flynn-taxonomy.md"};function S(D,a,p,h,M,m){const o=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=n('<h1 id="flynn-分类" tabindex="-1">Flynn 分类 <a class="header-anchor" href="#flynn-分类" aria-label="Permalink to &quot;Flynn 分类&quot;">​</a></h1><div class="epigraph"><p>按指令流与数据流的份数把机器分成 SISD、SIMD、MISD、MIMD；它不管缓存协议，只管「同时在飞的是一条指令还是很多」。 </p><footer>—— 据 Flynn, Very High-Speed Computing Systems, Proceedings of the IEEE, 1966 整理</footer></div><p><a href="/cs/fence-cost">上一课</a> 收束单核顺序与一致性进阶。单核 ILP 再挖也是一条指令流。<a href="/cs/superscalar-issue">超标量</a> 每拍多条，仍是同一 PC 家族。本课不重讲 fence drain。缺口是 <strong>Flynn 的四格：用指令流 × 数据流给后面的 VLIW、向量、SIMT、多核一个共同坐标系。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>乱序核、向量机、GPU、多 socket 在文献里都叫「并行」， intern 容易把发射宽度与核数相加。缺口不是再加一种 cache 态，而是<strong>先分箱：同一时刻有几条指令流、每条指令流操作几份数据。</strong> 后续课只在格子里走，不把 GPU 写成「很大的超标量」。</p><p><span class="marginnote">SISD：经典单核。SIMD：一条指令、向量数据。MISD：少见（某些流水脉动可硬塞）。MIMD：多核、多线程各有 PC。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>SISD：本课程前两单元的核。SIMD：后课向量 lane、以及 ISA 对照里的 <a href="/cs/simd-extensions">SIMD 扩展</a>——一条 opcode，多条 ALU。MIMD：后课多 socket、big.LITTLE。SIMT 是 SIMD 的控制实现：硬件上很多 lane 共享一个 PC，遇分支再发散，不是第四个 Flynn 类，下一课之后才拆。</p>',8)),(e(),i(d,null,{default:t(()=>[I(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E6%8C%87%E4%BB%A4%E6%B5%81%20%C3%97%20%E6%95%B0%E6%8D%AE%E6%B5%81%22%5D%20--%3E%20SISD%5B%22SISD%20%E5%8D%95%E6%B5%81%E5%8D%95%E6%95%B0%E6%8D%AE%22%5D%0A%20%20F%20--%3E%20SIMD%5B%22SIMD%20%E5%8D%95%E6%B5%81%E5%A4%9A%E6%95%B0%E6%8D%AE%22%5D%0A%20%20F%20--%3E%20MIMD%5B%22MIMD%20%E5%A4%9A%E6%B5%81%E5%A4%9A%E6%95%B0%E6%8D%AE%22%5D%0A%20%20SIMD%20--%3E%20SIMT%5B%22SIMT%EF%BC%9A%E5%85%B1%E4%BA%AB%20PC%20%E7%9A%84%20SIMD%20%E5%AE%9E%E7%8E%B0%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><a href="/cs/cpi-amdahl">阿姆达尔</a> 在 MIMD 上变成「串行段限制加速比」；SIMD 上变成「向量化比例」。二者不要混用同一个 \\(f\\)。一致性只出现在 MIMD（及 SIMD 核之间的共享内存），SISD 无需 <a href="/cs/mesi-protocol">MESI</a>。</p><p>本课声明边界：大模型栏的张量并行不是本栏的 Flynn 练习；这里只为 CPU/GPU/DSA 硬件分型。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 VLIW 的编译器打包写完，下一课。也不把数据流机当成第五类 Flynn——Dennis 的数据流是另一轴，再下一课。MISD 不展开。</p><p>后课默认：谈到并行先报 Flynn 格子。把多条独立操作塞进一个长指令字，是 VLIW/EPIC。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Flynn 用指令流与数据流分 SISD/SIMD/MIMD。</li><li>SIMT 是 SIMD 的控制包装，不是新格子。</li><li>VLIW 把并行打包交给编译器，下一课。</li><li>出处：Flynn, <em>IEEE Proc.</em>, 1966。</li></ul>',8))])}const A=l(E,[["render",S]]);export{_ as __pageData,A as default};
